import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const source = resolve(root, "scripts/gh-demo.html");
const target = resolve(root, "src/app/gh-demo/ghDemoHtml.ts");

const html = readFileSync(source, "utf8");

const file = `// Generated by scripts/build-gh-demo.mjs from scripts/gh-demo.html.
// Do not edit by hand: edit the source and run \`node scripts/build-gh-demo.mjs\`.
export const GH_DEMO_HTML = ${JSON.stringify(html)};
`;

writeFileSync(target, file, "utf8");
console.log(`Wrote ${target} (${html.length} chars)`);
